// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SigningMaker maker;
    FakeToken token;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new SigningMaker();
        token = new FakeToken();
    }

    function testFuzz_property(address to, uint256 nonce) public {
        vm.assume(to != address(0) && to != address(this));

        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory erc20s = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721s = new C.ERC721Asset[](0);
        uint256[] memory emptyIds = new uint256[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: erc20s,
            erc721Assets: erc721s
        });

        bytes memory emptySig = new bytes(0);
        c.fillOrder(order, emptySig, emptyIds);

        uint256 id = uint256(c.hashOrder(order));
        require(c.ownerOf(id) == address(this), "setup: mint failed");

        c.transferFrom(address(this), to, id);

        assertTrue(c.ownerOf(id) == to);
    }
}

contract SigningMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(uint256 id) public {
        // Any id is admissible: a token that was never minted must have no owner.
        // General rule: for every id without a live owner, ownerOf(id) must revert
        // (the token registry holds no stale owner for unminted/burned tokens).
        bool ok = true;
        try c.ownerOf(id) {
            ok = false;
        } catch {
            ok = true;
        }
        assertTrue(ok, "ownerOf must not return an owner for a token with no owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address actor, uint256 id) public {
        // keep the admissible domain wide: any non-sentinel actor, any id
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(0xdead));

        // attempt to burn token `id` by transferring it to the dead address.
        // Only `actor` (its owner) or an approved party can do this; we act as `actor`.
        vm.prank(actor);
        bool transferred;
        try c.transferFrom(actor, address(0xdead), id) {
            transferred = true;
        } catch {
            transferred = false;
        }

        // A completed burn must leave NO owner recorded for `id`:
        // ownerOf(id) must revert (or return the zero address) afterwards.
        // The buggy version keeps the stale owner in _ownerOf, so ownerOf(id)
        // still returns `actor` after the burn completed, violating the rule.
        bool owned;
        try c.ownerOf(id) returns (address o) {
            owned = (o != address(0));
        } catch {
            owned = false;
        }

        assertTrue(!(transferred && owned));
    }
}
